-- The assistant reads invoices, their lines, the vouchers and the balances (ADR-0060 #10,
-- docs/modules/ai.md §11); "today" is the Ulaanbaatar business date as in 0017.
CREATE VIEW ai.invoices AS
SELECT i.id, i.number, i.status, i.customer_id, c.code AS customer_code, c.name AS customer_name,
       i.order_id, i.order_number, i.branch_id, b.name AS branch_name, i.invoice_date, i.due_date,
       i.payment_method, i.subtotal, i.discount_total, i.total, i.vat_total, i.city_tax_total,
       i.total - i.open_amount AS paid_amount, i.open_amount,
       CASE WHEN i.status = 'VOID' THEN 'VOID' WHEN i.open_amount <= 0 THEN 'PAID'
            WHEN i.open_amount < i.total THEN 'PARTIAL' ELSE 'OPEN' END AS settlement,
       i.status = 'ISSUED' AND i.open_amount > 0
         AND i.due_date < (now() AT TIME ZONE 'Asia/Ulaanbaatar')::date AS overdue,
       CASE WHEN i.status = 'ISSUED' AND i.open_amount > 0
            THEN GREATEST((now() AT TIME ZONE 'Asia/Ulaanbaatar')::date - i.due_date, 0)
            ELSE 0 END AS days_overdue,
       (SELECT count(*) FROM public.invoice_lines l WHERE l.invoice_id = i.id) AS line_count,
       i.note, i.created_at, cu.full_name AS created_by_name, i.voided_at, i.void_reason
  FROM public.invoices i
  JOIN public.customers c ON c.id = i.customer_id
  LEFT JOIN public.branches b ON b.id = i.branch_id
  LEFT JOIN public.users cu ON cu.id = i.created_by;
--> statement-breakpoint

CREATE VIEW ai.invoice_lines AS
SELECT l.id, l.invoice_id, i.number AS invoice_number, i.status AS invoice_status, i.invoice_date,
       i.customer_id, c.name AS customer_name, l.line_no::integer AS line_no, l.product_id,
       l.product_sku AS sku, l.product_name, l.uom_name AS unit_name, l.qty, l.factor_snapshot,
       l.qty_base, l.warehouse_id, w.name AS warehouse_name, l.list_price, l.unit_price, l.subtotal,
       l.discount_amount, l.total, l.vat_type, l.vat_rate_pct, l.city_tax_rate_pct, l.vat_amount,
       l.city_tax_amount, l.returned_base
  FROM public.invoice_lines l
  JOIN public.invoices i ON i.id = l.invoice_id
  JOIN public.customers c ON c.id = i.customer_id
  LEFT JOIN public.warehouses w ON w.id = l.warehouse_id;
--> statement-breakpoint

CREATE VIEW ai.payments AS
SELECT p.id, p.number, p.status, p.kind, p.direction, p.money_account_id,
       m.code AS money_account_code, m.name AS money_account_name, m.kind AS money_account_kind,
       m.branch_id, b.name AS branch_name, p.customer_id, c.code AS customer_code,
       c.name AS customer_name, g.code AS gl_account_code, g.name AS gl_account_name, p.amount,
       p.paid_on, p.description, p.reference, p.counterparty_name,
       col.full_name AS collected_by_name, cu.full_name AS created_by_name, p.created_at,
       p.voided_at, p.void_reason
  FROM public.payments p
  JOIN public.money_accounts m ON m.id = p.money_account_id
  LEFT JOIN public.branches b ON b.id = m.branch_id
  LEFT JOIN public.customers c ON c.id = p.customer_id
  LEFT JOIN public.gl_accounts g ON g.id = p.gl_account_id
  LEFT JOIN public.users col ON col.id = p.collected_by
  LEFT JOIN public.users cu ON cu.id = p.created_by;
--> statement-breakpoint

CREATE VIEW ai.customer_balances AS
SELECT c.id AS customer_id, c.code AS customer_code, c.name AS customer_name,
       c.status AS customer_status, coalesce(cb.balance, 0) AS balance,
       coalesce(cb.open_invoices, 0) AS open_invoices,
       coalesce(cb.overdue_amount, 0) AS overdue_amount, cb.oldest_due_date, c.credit_limit,
       c.credit_hold, cb.updated_at
  FROM public.customers c
  LEFT JOIN public.customer_balances cb ON cb.customer_id = c.id;
--> statement-breakpoint

